 // LIF neuron model
 struct LIF {
     int neuron_id;
     int spike_time;
     float membrane_potential;
     float threshold;
     float refractory_time;
     bool refractory;

     LIF(int neuron_id, float threshold, float refractory_time) : neuron_id(neuron_id), spike_time(0), membrane_potential(0), threshold(threshold), refractory_time(refractory_time), refractory(false) {}
     void update(float dt) {
         if (refractory) {
             membrane_potential = 0;
             refractory = false;
         } else {
             membrane_potential += dt * (0.04 * membrane_potential * membrane_potential + 5 * membrane_potential + 140 - u);
             if (membrane_potential >= threshold) {
                 spike_time = clock() / CLOCKS_PER_SEC;
                 membrane_potential = 0;
                 refractory = true;
             }
         }
     }
 };

 // Hierarchical spiking network
 struct Network {
     vector<LIF> neurons;
     vector<Network> sub_networks;

     Network(int size, float threshold, float refractory_time) {
         for (int i = 0; i < size; i++) {
             neurons.push_back(LIF(i, threshold, refractory_time));
         }
     }
     void update(float dt) {
         for (auto& neuron : neurons) {
             neuron.update(dt);
         }
     }
     void add_sub_network(int size, float threshold, float refractory_time) {
         sub_networks.push_back(Network(size, threshold, refractory_time));
     }
     void connect_sub_networks() {
         for (int i = 0; i < sub_networks.size(); i++) {
             for (int j = 0; j < sub_networks[i].size(); j++) {
                 sub_networks[i].neurons[j].neuron_id = i * sub_networks[i].size() + j;
             }
         }
     }
     void run(int steps) {
         for (int i = 0; i < steps; i++) {
             update(1);
         }
     }
 };

