import torch
import snntorch as snn

# Define the LIF neuron model
class LIF(snn.Leaky):
    def __init__(self, threshold=1.0, reset=0.0, method='super', **kwargs):
        super(LIF, self).__init__(threshold=threshold, reset=reset, method=method, **kwargs)

    def forward(self, x):
        return super().forward(x)

# Define the STDP rule
class STDP(snn.STDP):
    def __init__(self, **kwargs):
        super(STDP, self).__init__(**kwargs)

    def forward(self, x):
        return super().forward(x)

# Define the SNN model
class SNNModel(snn.Sequential):
    def __init__(self):
        super(SNNModel, self).__init__(
            LIF(threshold=1.0, reset=0.0, method='super'),
            STDP()
        )

    def forward(self, x):
        return super().forward(x)

# Instantiate the model
model = SNNModel()

# Define the input data
input_data = torch.rand(10, 5)

# Run the model
output = model(input_data)

# Print the output
print(output)
