 Translate a PyTorch MLP classifier into a spiking network in Norse with surrogate gradient training. 
 We use a PyTorch LIF neuron model and surrogate gradients to train a 2-layer network with 128 neurons in each layer.

```python
import torch
import norse.torch as ntorch
from norse.torch.functional.lif import lif_neuron, lif_neuron_backward
import torch.nn as nn
import torch.optim as optim

# Define the PyTorch LIF neuron model
class LIF(nn.Module):
    def __init__(self):
        super(LIF, self).__init__()
        self.fc1 = nn.Linear(128, 128)
        self.fc2 = nn.Linear(128, 10)

    def forward(self, x):
        x = torch.relu(self.fc1(x))
        x = self.fc2(x)
        return x

# Define the surrogate gradient function
def surrogate_grad(x, y, dy):
    return dy * (x > 0).float()

# Define the surrogate gradient backward function
def surrogate_grad_backward(dy, dx, grad_output):
    return surrogate_grad(dx, dy, grad_output)

# Define the spiking network
class SpikingNetwork(nn.Module):
    def __init__(self):
        super(SpikingNetwork, self).__init__()
        self.fc1 = ntorch.LIFCell(128, 128)
        self.fc2 = ntorch.LIFCell(128, 10)

    def forward(self, x):
        x = self.fc1(x)
        x = self.fc2(x)
        return x

# Define the surrogate gradient function for the spiking network
def surrogate_grad_spiking(x, y, dy):
    return surrogate_grad(x, y, dy)

# Define the surrogate gradient backward function for the spiking network
def surrogate_grad_backward_spiking(dy, dx, grad_output):
    return surrogate_grad_backward(grad_output, dx, dy)

# Define the optimizer and loss function
optimizer = optim.SGD(SpikingNetwork().parameters(), lr=0.01)
loss_fn = nn.CrossEntropyLoss()

# Train the network
for epoch in range(10):
    for batch in data_loader:
        inputs, labels = batch
        optimizer.zero_grad()
        outputs = SpikingNetwork()(inputs)
        loss = loss_fn(outputs, labels)
        loss.backward()
        optimizer.step()
        # Apply surrogate gradients
        for param in SpikingNetwork().parameters():
            param.grad = surrogate_grad_spiking(param.data, outputs, param.grad)
        # Apply surrogate gradients backward
        for param in SpikingNetwork().parameters():
            param.grad = surrogate_grad_backward_spiking(param.grad, param.data, param.grad)
